21	/// A data structure similar to `EntityModification`, but tagged with a
22	/// block. We might eventually replace `EntityModification` with this, but
23	/// until the dust settles, we'll keep them separate.
24	///
25	/// This is geared towards how we persist entity changes: there are only
26	/// ever two operations we perform on them, clamping the range of an
27	/// existing entity version, and writing a new entity version.
28	///
29	/// The difference between `Insert` and `Overwrite` is that `Overwrite`
30	/// requires that we clamp an existing prior version of the entity at
31	/// `block`. We only ever get an `Overwrite` if such a version actually
32	/// exists. `Insert` simply inserts a new row into the underlying table,
33	/// assuming that there is no need to fix up any prior version.
34	///
35	/// The `end` field for `Insert` and `Overwrite` indicates whether the
36	/// entity exists now: if it is `None`, the entity currently exists, but if
37	/// it is `Some(_)`, it was deleted, for example, by folding a `Remove` or
38	/// `Overwrite` into this operation. The entity version will only be visible
39	/// before `end`, excluding `end`. This folding, which happens in
40	/// `append_row`, eliminates an update in the database which would otherwise
41	/// be needed to clamp the open block range of the entity to the block
42	/// contained in `end`
43	#[derive(Clone, CacheWeight, Debug, PartialEq, Eq)]
44	pub enum EntityModification {
45	    /// Insert the entity
46	    Insert {
47	        key: EntityKey,
48	        data: Arc<Entity>,
49	        block: BlockNumber,
50	        end: Option<BlockNumber>,
51	    },
52	    /// Update the entity by overwriting it
53	    Overwrite {
54	        key: EntityKey,
55	        data: Arc<Entity>,
56	        block: BlockNumber,
57	        end: Option<BlockNumber>,
58	    },
59	    /// Remove the entity
60	    Remove { key: EntityKey, block: BlockNumber },
61	}
62	
63	/// A helper struct for passing entity writes to the outside world, viz. the
64	/// SQL query generation that inserts rows
65	pub struct EntityWrite<'a> {
66	    pub id: &'a Id,
67	    pub entity: &'a Entity,
68	    pub causality_region: CausalityRegion,
69	    pub block: BlockNumber,
70	    // The end of the block range for which this write is valid. The value
71	    // of `end` itself is not included in the range
72	    pub end: Option<BlockNumber>,
73	}
74	
75	impl std::fmt::Display for EntityWrite<'_> {
76	    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
77	        let range = match self.end {
78	            Some(end) => format!("[{}, {}]", self.block, end - 1),
79	            None => format!("[{}, ∞)", self.block),
80	        };
81	        write!(f, "{}@{}", self.id, range)
82	    }
83	}
84	
85	impl<'a> TryFrom<&'a EntityModification> for EntityWrite<'a> {
86	    type Error = ();
87	
88	    fn try_from(emod: &'a EntityModification) -> Result<Self, Self::Error> {
89	        match emod {
90	            EntityModification::Insert {
91	                key,
92	                data,
93	                block,
94	                end,
95	            } => Ok(EntityWrite {
96	                id: &key.entity_id,
97	                entity: data,
98	                causality_region: key.causality_region,
99	                block: *block,
100	                end: *end,
101	            }),
102	            EntityModification::Overwrite {
103	                key,
104	                data,
105	                block,
106	                end,
107	            } => Ok(EntityWrite {
108	                id: &key.entity_id,
109	                entity: data,
110	                causality_region: key.causality_region,
111	                block: *block,
112	                end: *end,
113	            }),
114	
115	            EntityModification::Remove { .. } => Err(()),
116	        }
117	    }
118	}
119	
120	impl EntityModification {
121	    pub fn id(&self) -> &Id {
122	        match self {
123	            EntityModification::Insert { key, .. }
124	            | EntityModification::Overwrite { key, .. }
125	            | EntityModification::Remove { key, .. } => &key.entity_id,
126	        }
127	    }
128	
129	    fn block(&self) -> BlockNumber {
130	        match self {
131	            EntityModification::Insert { block, .. }
132	            | EntityModification::Overwrite { block, .. }
133	            | EntityModification::Remove { block, .. } => *block,
134	        }
135	    }
136	
137	    /// Return `true` if `self` requires a write operation, i.e.,insert of a
138	    /// new row, for either a new or an existing entity
139	    fn is_write(&self) -> bool {
140	        match self {
141	            EntityModification::Insert { .. } | EntityModification::Overwrite { .. } => true,
142	            EntityModification::Remove { .. } => false,
143	        }
144	    }
145	
146	    /// Return the details of the write if `self` is a write operation for a
147	    /// new or an existing entity
148	    fn as_write(&self) -> Option<EntityWrite<'_>> {
149	        EntityWrite::try_from(self).ok()
150	    }
151	
152	    /// Return `true` if `self` requires clamping of an existing version
153	    fn is_clamp(&self) -> bool {
154	        match self {
155	            EntityModification::Insert { .. } => false,
156	            EntityModification::Overwrite { .. } | EntityModification::Remove { .. } => true,
157	        }
158	    }
159	
160	    pub fn creates_entity(&self) -> bool {
161	        use EntityModification::*;
162	        match self {
163	            Insert { .. } => true,
164	            Overwrite { .. } | Remove { .. } => false,
165	        }
166	    }
167	
168	    fn entity_count_change(&self) -> i32 {
169	        match self {
170	            EntityModification::Insert { end: None, .. } => 1,
171	            EntityModification::Insert { end: Some(_), .. } => {
172	                // Insert followed by a remove
173	                0
174	            }
175	            EntityModification::Overwrite { end: None, .. } => 0,
176	            EntityModification::Overwrite { end: Some(_), .. } => {
177	                // Overwrite followed by a remove
178	                -1
179	            }
180	            EntityModification::Remove { .. } => -1,
181	        }
182	    }
183	
184	    fn clamp(&mut self, block: BlockNumber) -> Result<(), StoreError> {
185	        use EntityModification::*;
186	
187	        match self {
188	            Insert { end, .. } | Overwrite { end, .. } => {
189	                if end.is_some() {
190	                    return Err(internal_error!(
191	                        "can not clamp {:?} to block {}",
192	                        self,
193	                        block
194	                    ));
195	                }
196	                *end = Some(block);
197	            }
198	            Remove { .. } => {
199	                return Err(internal_error!(
200	                    "can not clamp block range for removal of {:?} to {}",
201	                    self,
202	                    block
203	                ))
204	            }
205	        }
206	        Ok(())
207	    }
